<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {clone,getStudio,roleLabels,saveStudio,type StudioPayload,type StudioRoute} from './content-studio-api';
const routeInfo=useRoute(),payload=ref<StudioPayload|null>(null),route=ref<StudioRoute|null>(null),message=ref(''),busy=ref(false),showAdd=ref<string|null>(null),dragged=ref<string|null>(null);
async function load(){payload.value=await getStudio();route.value=clone(payload.value.document.routes.find(r=>r.id===routeInfo.params.id)!);}onMounted(load);
const place=(id:string)=>payload.value?.document.places[id];const members=(stageId:string,groupId:string|null)=>route.value?.memberships.filter(m=>m.stageId===stageId&&m.groupId===groupId&&m.visible).sort((a,b)=>a.order-b.order)||[];
const unassigned=computed(()=>{const used=new Set(route.value?.memberships.filter(m=>m.visible).map(m=>m.placeId));return Object.values(payload.value?.document.places||{}).filter(p=>!used.has(p.id));});
function normalize(stageId:string,groupId:string|null){members(stageId,groupId).forEach((m,i)=>m.order=(i+1)*10);}
function move(placeId:string,direction:-1|1){const member=route.value!.memberships.find(m=>m.placeId===placeId)!;const list=members(member.stageId,member.groupId),index=list.findIndex(m=>m.placeId===placeId),other=list[index+direction];if(!other)return;[member.order,other.order]=[other.order,member.order];}
function moveTo(member:any,value:string){const [stageId,group]=value.split('|');member.stageId=stageId;member.groupId=group||null;member.order=members(stageId,member.groupId).length*10+10;}
function addPlace(stageId:string,placeId:string){route.value!.memberships.push({placeId,stageId,groupId:null,role:'secondary-stop',order:members(stageId,null).length*10+10,visible:true});showAdd.value=null;}
function addGroup(stage:any){stage.groups.push({id:`group-${crypto.randomUUID()}`,title:{zh:'新分组',en:''},summary:{zh:'',en:''},order:(stage.groups.length+1)*10,published:false,visible:true,archivedAt:null});}
function addStage(){route.value!.stages.push({id:`stage-${crypto.randomUUID()}`,title:{zh:'新阶段',en:''},summary:{zh:'',en:''},order:(route.value!.stages.length+1)*10,published:false,visible:true,archivedAt:null,groups:[]});}
function archiveStage(stage:any){if(!confirm(`归档阶段“${stage.title.zh}”？阶段内地点关系会保留但不再公开。`))return;stage.archivedAt=new Date().toISOString();stage.visible=false;route.value!.memberships.filter(m=>m.stageId===stage.id).forEach(m=>m.visible=false);}
function archiveGroup(stage:any,group:any){if(!confirm(`归档“${group.title.zh}”？其中地点会移回本阶段其他地点。`))return;route.value!.memberships.filter(m=>m.groupId===group.id).forEach(m=>m.groupId=null);group.archivedAt=new Date().toISOString();group.visible=false;}
function drop(stageId:string,groupId:string|null){if(!dragged.value)return;const member=route.value!.memberships.find(m=>m.placeId===dragged.value);if(member){member.stageId=stageId;member.groupId=groupId;member.order=members(stageId,groupId).length*10+10;}dragged.value=null;}
async function save(){if(!payload.value||!route.value)return;busy.value=true;try{const doc=clone(payload.value.document),index=doc.routes.findIndex(r=>r.id===route.value!.id);doc.routes[index]=clone(route.value);const r=await saveStudio(payload.value,doc,'route',route.value.id,`修改路线：${route.value.name.zh}`);message.value=`草稿已保存（版本 ${r.draftRevision}），公开网站尚未改变。`;await load();}catch(e){message.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><div v-if="payload&&route" class="workspace-page studio-page route-studio"><div class="workspace-title"><div><RouterLink to="/studio/routes">← 返回路线</RouterLink><p class="kicker">路线可视化编辑</p><input v-model="route.name.zh" class="inline-title"><textarea v-model="route.summary.zh" rows="2"></textarea><div class="theme-checks"><label><input v-model="route.published" type="checkbox">公开</label><label><input v-model="route.featured" type="checkbox">Explore 推荐</label><label>顺序<input v-model.number="route.order" type="number"></label></div></div><div class="workspace-actions"><a class="button quiet" :href="`/zh/route/${route.slug}/`" target="_blank">预览公开页</a><button class="primary-action" :disabled="busy" @click="save">保存草稿</button></div></div><p v-if="message" class="inline-message">{{message}}</p>
<section v-for="(stage,si) in route.stages.filter(s=>!s.archivedAt).sort((a,b)=>a.order-b.order)" :key="stage.id" class="route-stage-card"><header><span>{{String(si+1).padStart(2,'0')}}</span><input v-model="stage.title.zh"><button class="quiet" @click="addGroup(stage)">＋ 添加分组</button><button class="remove-button" @click="archiveStage(stage)">归档阶段</button></header>
<div v-for="group in stage.groups.filter(g=>!g.archivedAt).sort((a,b)=>a.order-b.order)" :key="group.id" class="route-group" @dragover.prevent @drop="drop(stage.id,group.id)"><div class="route-group-heading"><input v-model="group.title.zh"><button class="remove-button" @click="archiveGroup(stage,group)">归档</button></div><div class="route-group-section"><h4>值得停留</h4><article v-for="member in members(stage.id,group.id).filter(m=>!['service','junction'].includes(m.role))" :key="member.placeId" draggable="true" @dragstart="dragged=member.placeId" class="route-place-row"><span>☰</span><RouterLink :to="`/studio/places/${member.placeId}`"><strong>{{place(member.placeId)?.name.zh}}</strong><small>{{member.placeId}}</small></RouterLink><select v-model="member.role"><option v-for="(label,key) in roleLabels" :value="key">{{label}}</option></select><button @click="move(member.placeId,-1)">↑</button><button @click="move(member.placeId,1)">↓</button><select :value="`${member.stageId}|${member.groupId||''}`" @change="moveTo(member,($event.target as HTMLSelectElement).value)"><optgroup v-for="s in route.stages.filter(x=>!x.archivedAt)" :label="s.title.zh"><option :value="`${s.id}|`">{{s.title.zh}} · 未分组</option><option v-for="g in s.groups.filter(x=>!x.archivedAt)" :value="`${s.id}|${g.id}`">{{g.title.zh}}</option></optgroup></select></article><h4>服务与路口</h4><article v-for="member in members(stage.id,group.id).filter(m=>['service','junction'].includes(m.role))" :key="member.placeId" class="route-place-row"><span>☰</span><RouterLink :to="`/studio/places/${member.placeId}`"><strong>{{place(member.placeId)?.name.zh}}</strong><small>{{member.placeId}}</small></RouterLink><select v-model="member.role"><option v-for="(label,key) in roleLabels" :value="key">{{label}}</option></select><button @click="move(member.placeId,-1)">↑</button><button @click="move(member.placeId,1)">↓</button></article></div></div>
<div class="route-group fallback" @dragover.prevent @drop="drop(stage.id,null)"><h3>{{stage.groups.some(g=>!g.archivedAt)?'本阶段其他地点':'阶段地点'}}</h3><article v-for="member in members(stage.id,null)" :key="member.placeId" draggable="true" @dragstart="dragged=member.placeId" class="route-place-row"><span>☰</span><RouterLink :to="`/studio/places/${member.placeId}`"><strong>{{place(member.placeId)?.name.zh}}</strong><small>{{member.placeId}}</small></RouterLink><select v-model="member.role"><option v-for="(label,key) in roleLabels" :value="key">{{label}}</option></select><button @click="move(member.placeId,-1)">↑</button><button @click="move(member.placeId,1)">↓</button><select :value="`${member.stageId}|`" @change="moveTo(member,($event.target as HTMLSelectElement).value)"><optgroup v-for="s in route.stages.filter(x=>!x.archivedAt)" :label="s.title.zh"><option :value="`${s.id}|`">{{s.title.zh}} · 未分组</option><option v-for="g in s.groups.filter(x=>!x.archivedAt)" :value="`${s.id}|${g.id}`">{{g.title.zh}}</option></optgroup></select></article><button class="quiet" @click="showAdd=showAdd===stage.id?null:stage.id">＋ 添加已有地点</button><div v-if="showAdd===stage.id" class="available-content"><button v-for="p in unassigned" :key="p.id" @click="addPlace(stage.id,p.id)">{{p.name.zh}} · {{p.id}}</button><p v-if="!unassigned.length">所有地点已经在这条路线中。</p></div></div></section><button class="button quiet" @click="addStage">＋ 新增阶段</button><div class="editor-action-bar"><button class="primary-action" :disabled="busy" @click="save">保存路线草稿</button></div></div></template>
